  function inject(){if(!document.getElementById('course-tool-v3'))document.head?.insertAdjacentHTML('beforeend',css);if(!document.getElementById('course-tool-v5-parts'))document.head?.insertAdjacentHTML('beforeend',partsCss);if(!document.getElementById('course-tool-v4-premium'))document.head?.insertAdjacentHTML('beforeend',premiumCss)}
  function visual(slide,course){
    const v=slide.visual||'';
    if(course?.id==='parts-of-speech-mastery'){
      const card=(b,s,c='')=>`<div class="course-pos-card ${c}"><b>${b}</b><strong>${s}</strong></div>`;
      const row=(b,s)=>`<div><b>${b}</b><span>${s}</span></div>`;
      const board=(title,content,meta='SOURCE VISUAL')=>`<div class="course-pos-visual"><div class="course-pos-board"><div class="course-pos-board-title"><span>${title}</span><em>${meta}</em></div>${content}</div></div>`;
      if(v==='pos-overview')return board('SENTENCE → JOB → POS',`<div class="course-pos-flow">${card('01','Sentence','blue')}<i>→</i>${card('02','Words at work','green')}<i>→</i>${card('03','Each word has a job','gold')}<i>→</i>${card('04','Part of Speech','purple')}</div>`,'BIG PICTURE');
      if(v==='pos-workers')return board('THE EIGHT WORKERS',`<div class="course-pos-grid">${card('NOUN','name word','green')}${card('PRONOUN','replace noun','blue')}${card('ADJECTIVE','describe noun','purple')}${card('VERB','action / state','gold')}${card('ADVERB','modify V/Adj/Adv','purple')}${card('PREPOSITION','relation + object','blue')}${card('CONJUNCTION','join units','green')}${card('INTERJECTION','emotion burst','gold')}</div>`,'8 POS');
      if(v==='pos-form-function')return board('FUNCTION NOT FORM',`<div class="course-pos-ruleline"><div><b>NAME</b><span>Who/what? → Noun</span></div><div><b>REPLACE</b><span>Instead of noun → Pronoun</span></div><div><b>DESCRIBE</b><span>Noun modifier → Adjective</span></div></div><div class="course-pos-ruleline"><div><b>ACTION</b><span>What happens? → Verb</span></div><div><b>MODIFY</b><span>How/when/where? → Adverb</span></div><div><b>JOIN</b><span>Only joins → Conjunction</span></div></div>`,'CORE RULE');
      if(v==='pos-round-switcher')return board('ROUND · SAME WORD SWITCHER',`<div class="course-pos-atlas">${card('ADJ','earth is round','blue')}${card('ADV','came round','green')}${card('PREP','round the fire','purple')}${card('NOUN','first round','gold')}${card('VERB','rounded corner','blue')}</div>`,'GOLDMINE');
      if(v==='pos-noun-wheel')return board('NOUN TYPE WHEEL',`<div class="course-pos-branch"><div class="course-pos-root">NOUN = NAME</div><div class="course-pos-branches">${card('PROPER','Dhaka','blue')}${card('COMMON','city','green')}${card('COLLECTIVE','army','purple')}${card('MATERIAL','cotton','gold')}${card('ABSTRACT','honesty','purple')}${card('EXTRA LENS','count / case','blue')}${card('FUNCTION','subject / object','green')}${card('APPOSITION','rename noun','gold')}</div></div>`,'NOUN');
      if(v==='pos-countability')return board('COUNTABILITY GATE',`<div class="course-pos-warning">${card('COUNTABLE','a chair · many chairs','green')}${card('UNCOUNTABLE','much information · a piece of advice','blue')}</div><div class="course-pos-ruleline"><div><b>ARTICLE</b><span>a/an possible</span></div><div><b>QUANTITY</b><span>many/few vs much/little</span></div><div><b>TRAP</b><span>informations ✗</span></div></div>`,'NOUN');
      if(v==='pos-case-function')return board('CASE + SENTENCE FUNCTION',`<div class="course-pos-atlas">${card('SUBJECT','Karim went','green')}${card('OBJECT','I saw him','blue')}${card('POSSESSIVE','Karim’s book','gold')}${card('VOCATIVE','Karim, come','purple')}${card('COMPLEMENT','He is a doctor','blue')}${card('APPOSITIVE','Rahim, my cousin','green')}</div>`,'CASE');
      if(v==='pos-noun-equivalents')return board('NOUN-EQUIVALENT LENS',`<div class="course-pos-grid three">${card('GERUND','Swimming is useful','green')}${card('INFINITIVE','To err is human','blue')}${card('THE + ADJ','The poor need help','gold')}</div>`,'FUNCTION');
      if(v==='pos-pronoun-atlas')return board('PRONOUN FAMILY ATLAS',`<div class="course-pos-grid">${card('PERSONAL','he · they','blue')}${card('POSSESSIVE','mine · ours','gold')}${card('REFLEXIVE','himself','green')}${card('EMPHATIC','he himself','purple')}${card('RELATIVE','who · whom','blue')}${card('DEMONSTRATIVE','this · that','green')}${card('INDEFINITE','someone','gold')}${card('RECIPROCAL','each other','purple')}</div>`,'PRONOUN');
      if(v==='pos-antecedent-tree')return board('WHO / WHOM DECISION TREE',`<div class="course-pos-branch"><div class="course-pos-root">PERSON / THING + CASE</div><div class="course-pos-branches">${card('SUBJECT','who came','green')}${card('OBJECT','whom I met','blue')}${card('POSSESSION','whose book','gold')}${card('THING','which / that','purple')}</div><div class="course-pos-ruleline"><div><b>HE TEST</b><span>who = he</span></div><div><b>HIM TEST</b><span>whom = him</span></div><div><b>ANTECEDENT</b><span>what = no noun</span></div></div></div>`,'PRONOUN');
      if(v==='pos-agreement')return board('AGREEMENT HEADWORD',`<div class="course-pos-ladder">${card('01','each / every → singular','green')}<i>↓</i>${card('02','of + plural noun is not the head','blue')}<i>↓</i>${card('03','Each of them is ready.','gold')}</div>`,'PRONOUN');
      if(v==='pos-article-sound')return board('A / AN · SOUND GATE',`<div class="course-pos-flow">${card('CONSONANT SOUND','a university · a European','blue')}<i>⇄</i>${card('VOWEL SOUND','an hour · an honest man','green')}<i>⇄</i>${card('INITIALISM','an MBA · an M.A.','gold')}</div>`,'ADJECTIVE');
      if(v==='pos-degree-rail')return board('DEGREE RAIL · POS CONTEXT',`<div class="course-pos-ladder">${card('01','POSITIVE · bright','green')}<i>↓</i>${card('02','COMPARATIVE · brighter than','blue')}<i>↓</i>${card('03','SUPERLATIVE · the brightest','purple')}</div>`,'ADJECTIVE');
      if(v==='pos-osascomp')return board('FEW / LITTLE + OSASCOMP',`<div class="course-pos-grid three">${card('FEW','almost no countable','blue')}${card('A FEW','some countable','green')}${card('LITTLE','almost no uncountable','purple')}</div><div class="course-pos-chipline"><span>Opinion</span><span>Size</span><span>Age</span><span>Shape</span><span>Colour</span><span>Origin</span><span>Material</span><span>Purpose</span></div>`,'ADJECTIVE');
      if(v==='pos-linking')return board('LINKING VERB COMPLEMENT',`<div class="course-pos-warning">${card('LINKING + ADJ','The soup tastes sweet.','green')}${card('ACTION + ADV','She tasted it carefully.','blue')}</div><div class="course-pos-ruleline"><div><b>BE</b><span>is/seem/look/feel</span></div><div><b>COMPLEMENT</b><span>noun or adjective</span></div><div><b>TRAP</b><span>sweetly ✗ in exam line</span></div></div>`,'VERB / ADJ');
      if(v==='pos-finite-fork')return board('FINITE / NON-FINITE FORK',`<div class="course-pos-flow">${card('FINITE','He goes · He went','green')}<i>⇄</i>${card('INFINITIVE','to go / bare go','blue')}<i>⇄</i>${card('GERUND','going as noun','purple')}<i>⇄</i>${card('PARTICIPLE','going / gone','gold')}</div>`,'VERB');
      if(v==='pos-transitivity')return board('OBJECT LANES',`<div class="course-pos-grid three">${card('TRANSITIVE','kicked the ball','blue')}${card('INTRANSITIVE','slept','green')}${card('DITRANSITIVE','gave me a book','purple')}</div><div class="course-pos-ruleline"><div><b>WHOM/WHAT?</b><span>object test</span></div><div><b>PASSIVE</b><span>usually transitive</span></div><div><b>NO OBJECT</b><span>intransitive</span></div></div>`,'VERB');
      if(v==='pos-v-ing-split')return board('V-ING · THREE JOBS',`<div class="course-pos-grid three">${card('GERUND','Swimming is fun.','green')}${card('PARTICIPLE','a swimming bird','blue')}${card('CONTINUOUS','is swimming','purple')}</div>`,'VERB');
      if(v==='pos-causative')return board('CAUSATIVE PATTERN GRID',`<div class="course-pos-mini-table">${row('make + O + bare V','made me wait = force')}${row('let + O + bare V','let him go = permission')}${row('have + O + V3','had my hair cut = arrange')}${row('get + O + to V','get him to sign = persuade')}${row('help + (to) V','helped me to lift = optional to')}</div>`,'VERB');
      if(v==='pos-adverb-radar')return board('ADVERB QUESTION RADAR',`<div class="course-pos-grid three">${card('MANNER','How? quickly','green')}${card('PLACE','Where? here','blue')}${card('TIME','When? yesterday','gold')}${card('FREQUENCY','How often? often','purple')}${card('DEGREE','How much? very','blue')}${card('SENTENCE','Speaker attitude','green')}</div>`,'ADVERB');
      if(v==='pos-ly-gate')return board('-LY GATE · EXCEPTIONS',`<div class="course-pos-warning">${card('-LY ADVERB','slow → slowly · beauty → beautifully','green')}${card('-LY ADJECTIVE','friendly · lovely · likely · deadly','purple')}</div><div class="course-pos-chipline"><span>hard</span><span>hardly</span><span>late</span><span>lately</span><span>near</span><span>nearly</span><span>high</span><span>highly</span></div>`,'ADVERB');
      if(v==='pos-pair-traps')return board('LOOK-ALIKE PAIRS',`<div class="course-pos-ladder">${card('HARD / HARDLY','effort / almost not','green')}<i>↓</i>${card('LATE / LATELY','not early / recently','blue')}<i>↓</i>${card('NEAR / NEARLY','close / almost','purple')}<i>↓</i>${card('GOOD / WELL','quality / manner-health','gold')}</div>`,'ADVERB');
      if(v==='pos-position-lane')return board('ADVERB POSITION LANE',`<div class="course-pos-flow">${card('FREQUENCY','always + main verb','green')}<i>→</i>${card('MANNER','verb/object after','blue')}<i>→</i>${card('PLACE','before time','purple')}<i>→</i>${card('TIME','end/front','gold')}</div>`,'ADVERB');
      if(v==='pos-object-gate')return board('OBJECT TEST',`<div class="course-pos-warning">${card('OBJECT EXISTS','up the tree → PREPOSITION','blue')}${card('NO OBJECT','looked up → ADVERBIAL PARTICLE','green')}</div><div class="course-pos-ruleline"><div><b>CHECK</b><span>ডানে noun-like group?</span></div><div><b>YES</b><span>preposition</span></div><div><b>NO</b><span>usually adverb</span></div></div>`,'PREPOSITION');
      if(v==='pos-relation-map')return board('RELATION MAP',`<div class="course-pos-grid three">${card('TIME','at · on · in','blue')}${card('PLACE','at · on · in','green')}${card('DIRECTION','to · into · from','purple')}${card('AGENT','by Shakespeare','gold')}${card('TOOL','with a knife','blue')}${card('CAUSE','of cholera · from overwork','green')}</div>`,'PREPOSITION');
      if(v==='pos-prep-conj')return board('NOUN / CLAUSE / ZERO FORK',`<div class="course-pos-flow">${card('NOUN','since Monday','blue')}<i>→</i>${card('CLAUSE','since he left','green')}<i>→</i>${card('ZERO','since.','purple')}</div><div class="course-pos-ruleline"><div><b>NOUN</b><span>Preposition</span></div><div><b>CLAUSE</b><span>Conjunction</span></div><div><b>NOTHING</b><span>Adverb</span></div></div>`,'PREP / CONJ');
      if(v==='pos-fixed-combos')return board('FIXED COMBO + BLACKLIST',`<div class="course-pos-mini-table">${row('fond / afraid / proud','of')}${row('depend / rely','on')}${row('superior / prefer','to')}${row('discuss / enter / resemble','no extra preposition')}${row('despite','no of')}${row('look forward to','+ gerund')}</div>`,'PREPOSITION');
      if(v==='pos-conj-families')return board('THREE CONJUNCTION FAMILIES',`<div class="course-pos-branch"><div class="course-pos-root">CONJUNCTION = JOINER</div><div class="course-pos-branches">${card('COORDINATING','FANBOYS','blue')}${card('SUBORDINATING','because · if','green')}${card('CORRELATIVE','either…or','purple')}${card('RELATIVE NOTE','who/that member','gold')}</div></div>`,'CONJUNCTION');
      if(v==='pos-fanboys')return board('FANBOYS RAIL',`<div class="course-pos-chipline"><span>F · for</span><span>A · and</span><span>N · nor</span><span>B · but</span><span>O · or</span><span>Y · yet</span><span>S · so</span></div><div class="course-pos-ruleline"><div><b>EQUAL</b><span>two equal units</span></div><div><b>JOIN</b><span>coordinating</span></div><div><b>TRAP</b><span>because is subordinate</span></div></div>`,'CONJUNCTION');
      if(v==='pos-connector-radar')return board('CONNECTOR MEANING RADAR',`<div class="course-pos-grid three">${card('TIME','when · after','blue')}${card('REASON','because · since','green')}${card('CONDITION','if · unless','purple')}${card('CONCESSION','although · though','gold')}${card('PURPOSE','so that','blue')}${card('RESULT','so…that','green')}</div>`,'CONJUNCTION');
      if(v==='pos-parallelism')return board('CORRELATIVE PARALLELISM',`<div class="course-pos-warning">${card('RIGHT','not only reading but also writing','green')}${card('WRONG','not only reading but also to write','purple')}</div><div class="course-pos-chipline"><span>both…and</span><span>either…or</span><span>neither…nor</span><span>not only…but also</span></div>`,'CONJUNCTION');
      if(v==='pos-interjection-map')return board('EMOTION → BURST WORD',`<div class="course-pos-grid three">${card('SORROW','Alas!','purple')}${card('JOY','Hurrah!','green')}${card('SURPRISE','Oh! / What!','gold')}${card('APPROVAL','Bravo!','blue')}${card('ATTENTION','Hey!','green')}${card('QUESTION','What book? ≠ What!','blue')}</div>`,'INTERJECTION');
      if(v==='pos-goldmine')return board('SAME WORD ≠ SAME POS',`<div class="course-pos-grid three">${card('ROUND','5 roles','blue')}${card('LIKE','verb / prep','green')}${card('BUT','conj / prep / adv','purple')}${card('AS','conj / role / adv','gold')}${card('THAT','5 possible roles','blue')}${card('HOME','adv / noun / adj','green')}</div>`,'GOLDMINE');
      if(v==='pos-stress-pairs')return board('NOUN ↔ VERB STRESS',`<div class="course-pos-stress">${card('RECORD','REcord / reCORD','blue')} ${card('PRESENT','PREsent / preSENT','green')} ${card('OBJECT','OBject / obJECT','purple')} ${card('PERMIT','PERmit / perMIT','gold')}</div>`,'GOLDMINE');
      if(v==='pos-algorithm')return board('5-STEP IDENTIFICATION ALGORITHM',`<div class="course-pos-steps"><div><b>1</b><span>Find the finite verb</span></div><div><b>2</b><span>Find subject and object</span></div><div><b>3</b><span>Ask what the word modifies or joins</span></div><div><b>4</b><span>Check the right side: noun / clause / nothing</span></div><div><b>5</b><span>Name POS by function</span></div></div>`,'METHOD');
      if(v==='pos-signal-cheatsheet')return board('SIGNAL → HYPOTHESIS → CONFIRM',`<div class="course-pos-mini-table">${row('a/an/the/my + noun','adjective? describe the noun')}${row('word + noun phrase','preposition? noun is object')}${row('word + subject + verb','conjunction/relative?')}${row('end + no object','adverb/particle?')}${row('be/seem/look + word','adjective complement?')}${row('V-ing / to + V1','gerund/participle/infinitive?')}</div>`,'METHOD');
      if(v==='pos-confusing-pairs')return board('CONFUSING PAIR CARDS',`<div class="course-pos-grid three">${card('REASON','because + clause / because of + noun','blue')}${card('CONCESSION','although + clause / despite + noun','green')}${card('TIME','during + noun / while + clause','purple')}${card('SIMILARITY','like + noun / as + clause','gold')}${card('INVERSION','no sooner…than','blue')}${card('INVERSION','hardly…when','green')}</div>`,'METHOD');
      if(v==='pos-exam-strategy')return board('STEM → SOLVER',`<div class="course-pos-mini-table">${row('Direct rule','definition / type')}${row('Identify POS','function in sentence')}${row('Same word','right-side test')}${row('Error detection','case / adj-adv / extra prep')}${row('Fill blank','article / prep / pair')}${row('Trap','hardly / but / since / enough')}</div>`,'STRATEGY');
      if(v==='pos-checklist')return board('30-SECOND HALL CHECKLIST',`<div class="course-pos-steps"><div><b>1</b><span>ডানে 3–4 word পড়ো</span></div><div><b>2</b><span>Finite verb খুঁজো</span></div><div><b>3</b><span>Object আছে?</span></div><div><b>4</b><span>Noun না verb modify?</span></div><div><b>5</b><span>V-ing / to form-এর job</span></div><div><b>6</b><span>Meaning + option label confirm</span></div></div>`,'STRATEGY');
      if(v==='pos-trap-cards')return board('TRAP → ACTUAL RULE → MEMORY',`<div class="course-pos-warning">${card('MISCONCEPTION','সব -ly adverb','purple')}${card('ACTUAL','friendly adjective; linking + adjective','green')}</div><div class="course-pos-ruleline"><div><b>EXAM ASK</b><span>feel badly? tastes sweetly?</span></div><div><b>RIGHT</b><span>feel bad · taste sweet</span></div><div><b>MEMORY</b><span>function, not ending</span></div></div>`,'TRAP LAB');
      if(v==='pos-micro-rules')return board('40 MICRO-RULES · SCAN MODE',`<div class="course-pos-chipline"><span>Function</span><span>Object</span><span>Clause</span><span>Modify</span><span>Linking + adj</span><span>Gerund</span><span>who/whom</span><span>each singular</span><span>hard/hardly</span><span>enough</span><span>to + gerund</span><span>superior to</span><span>FANBOYS</span><span>that 5 ways</span><span>but 3 ways</span><span>go home</span></div>`,'REVISION');
      if(v==='pos-rapid-revision')return board('5-MINUTE RAPID REVISION',`<div class="course-pos-grid three">${card('8 POS','eight jobs','blue')}${card('GOLDEN','function, not form','green')}${card('RIGHT SIDE','noun / clause / zero','purple')}${card('MODIFY','noun → adj; V → adv','gold')}${card('V-ING','noun / modifier / chain','blue')}${card('TRAPS','case / prep / uncountable','green')}</div>`,'REVISION');
      if(v==='pos-memory-map')return board('MASTER MEMORY MAP',`<div class="course-pos-memory"><div class="course-pos-root">PARTS OF SPEECH</div><div class="course-pos-branches">${card('8 JOBS','types + rules','blue')}${card('EXCEPTIONS','same word + pairs','green')}${card('TRAPS','linking + case + prep','purple')}${card('5-STEP ID','solver engine','gold')}</div></div>`,'REVISION');
      if(v==='pos-source-bank')return board('SOURCE MCQ ROUTE',`<div class="course-pos-ladder">${card('BASIC','Q01–Q16','green')}<i>↓</i>${card('INTERMEDIATE','Q17–Q40','blue')}<i>↓</i>${card('ADMISSION','Q41–Q68','purple')}<i>↓</i>${card('TRAP / ADVANCED','Q69–Q80','gold')}</div>`,'80 SOURCE MCQs');
      if(v==='pos-answer-key')return board('80-ITEM ANSWER KEY',`<div class="course-pos-grid three">${card('01–20','B C B B B B C C B C…','blue')}${card('21–40','B B B B C B B B B B…','green')}${card('41–60','C C B C B C D B C B…','purple')}${card('61–80','B C B C C C B C C C…','gold')}</div>`,'SOURCE KEY');
      if(v==='pos-topic-map')return board('COMPLETE TOPIC MAP',`<div class="course-pos-memory"><div class="course-pos-root">8 JOBS</div><div class="course-pos-branches">${card('NOUN','types · count · case','green')}${card('PRONOUN','case · agreement','blue')}${card('ADJECTIVE','articles · degree · order','purple')}${card('VERB','finite · linking · verbals','gold')}${card('ADVERB','types · pairs · position','blue')}${card('PREPOSITION','object · fixed combos','green')}${card('CONJUNCTION','families · parallelism','purple')}${card('INTERJECTION','emotion map','gold')}</div></div>`,'FINAL RECALL');
      return board('PARTS OF SPEECH',`<div class="course-pos-flow">${card('FUNCTION','not form','blue')}<i>→</i>${card('SIGNAL','right-side test','green')}<i>→</i>${card('ANSWER','name the job','gold')}</div>`,'VISUAL LESSON');
    }
    if(course?.id==='phrase-clause-mastery'){
      if(v==='group-unit')return '<div class="course-visual-v3"><div class="course-phrase-split"><div class="course-phrase-panel phrase"><b>PHRASE</b><strong>in the garden</strong><span>group / no full subject + finite verb</span></div><div class="course-phrase-divider">⇄</div><div class="course-phrase-panel clause"><b>CLAUSE</b><strong>when he came</strong><span>he + came / subject + finite verb</span></div></div></div>';
      if(v==='detector')return '<div class="course-visual-v3"><div class="course-finite-detector"><div><b>01</b><span>SUBJECT</span><small>কে / কী?</small></div><i>→</i><div><b>02</b><span>FINITE VERB</span><small>tense আছে?</small></div><i>→</i><div><b>03</b><span>CONNECTOR</span><small>when · who · because</small></div><i>→</i><div><b>04</b><span>FUNCTION</span><small>noun · adjective · adverb</small></div></div></div>';
      if(v==='function-map')return '<div class="course-visual-v3"><div class="course-function-sorter"><div class="noun"><b>NOUN FUNCTION</b><span>Reading books</span><small>subject / object</small></div><div class="adjective"><b>ADJECTIVE FUNCTION</b><span>eager to learn</span><small>describes a noun</small></div><div class="adverb"><b>ADVERB FUNCTION</b><span>with confidence</span><small>modifies a verb</small></div></div></div>';
      if(v==='family-grid')return '<div class="course-visual-v3"><div class="course-phrase-family"><div><b>NOUN</b><span>the tall boy</span></div><div><b>ADJECTIVE</b><span>eager to learn</span></div><div><b>ADVERB</b><span>with confidence</span></div><div><b>PREPOSITIONAL</b><span>in the room</span></div><div><b>INFINITIVE</b><span>to study</span></div><div><b>GERUND</b><span>Reading books</span></div><div><b>PARTICIPIAL</b><span>walking along</span></div><div><b>APPOSITIVE</b><span>my best friend</span></div></div></div>';
      if(v==='clause-tree')return '<div class="course-visual-v3"><div class="course-clause-map"><div class="course-clause-root"><b>CLAUSE</b><span>subject + finite verb</span></div><div class="course-clause-branches"><div><b>MAIN</b><span>complete alone</span></div><div><b>NOUN</b><span>subject / object</span></div><div><b>RELATIVE</b><span>describes noun</span></div><div><b>ADVERBIAL</b><span>time / reason / condition</span></div></div></div></div>';
      if(v==='connector-radar')return '<div class="course-visual-v3"><div class="course-connector-radar"><div><b>TIME</b><span>when · after</span></div><div><b>REASON</b><span>because · since</span></div><div><b>CONDITION</b><span>if · unless</span></div><div><b>CONCESSION</b><span>although</span></div><div><b>PURPOSE</b><span>so that</span></div><div><b>RESULT</b><span>so…that</span></div></div></div>';
      if(v==='analysis-lane')return '<div class="course-visual-v3"><div class="course-analysis-lane"><div><b>SUBJECT</b><span>The tall gentleman</span></div><i>+</i><div><b>MODIFIER</b><span>standing by the door</span></div><i>+</i><div><b>FINITE VERB</b><span>is</span></div><i>+</i><div><b>COMPLEMENT</b><span>the bank manager</span></div></div></div>';
      if(v==='count-lane')return '<div class="course-visual-v3"><div class="course-count-lane"><div><b>1 FINITE VERB</b><span>He wants <em>to read</em>.</span><small>1 clause + infinitive phrase</small></div><div><b>2 FINITE VERBS</b><span>He reads because he likes it.</span><small>2 clause units</small></div></div></div>';
      if(v==='conversion-arrows')return '<div class="course-visual-v3"><div class="course-conversion-flow"><div><b>CLAUSE</b><span>After he finished</span></div><i>→</i><div><b>SHARED SUBJECT</b><span>he = implied</span></div><i>→</i><div><b>PHRASE</b><span>After finishing</span></div></div></div>';
      if(v==='warning-lane')return '<div class="course-visual-v3"><div class="course-warning-lane"><div class="safe"><b>MATCH</b><span>Walking…, I saw a bird.</span><small>modifier subject = I</small></div><div class="warn"><b>CHECK</b><span>Walking…, the bird was seen.</span><small>dangling / awkward meaning</small></div></div></div>';
      if(v==='trap-sorter')return '<div class="course-visual-v3"><div class="course-trap-sorter"><div><b>GROUP</b><span>to read · in the room</span></div><i>↓</i><div><b>FINITE TEST</b><span>subject + tense?</span></div><i>↓</i><div><b>FINAL LABEL</b><span>phrase / clause + function</span></div></div></div>';
      if(v==='revision-cards')return '<div class="course-visual-v3"><div class="course-revision-cards"><div><b>1</b><span>Subject</span></div><div><b>2</b><span>Finite verb</span></div><div><b>3</b><span>Connector</span></div><div><b>4</b><span>Function</span></div><div><b>5</b><span>Meaning</span></div></div></div>';
      return '<div class="course-visual-v3"><div class="course-trap-sorter"><div><b>PHRASE</b><span>no finite pair</span></div><i>→</i><div><b>CLAUSE</b><span>subject + finite verb</span></div></div></div>';
    }
    if(course?.id==='degree-mastery'){
      const label=String(slide.title||'').toLowerCase();
      if(v==='filter'||/filter|solver|trap|revision/.test(label))return '<div class="course-visual-v3"><div class="course-degree-filter"><div><b>SIGNAL</b><span>than · as · the</span></div><i>→</i><div><b>FORM</b><span>positive · comparative · superlative</span></div><i>→</i><div><b>CHECK</b><span>noun · article · meaning</span></div></div></div>';
      if(v==='focus'||/foundation|link|pattern/.test(label))return '<div class="course-visual-v3"><div class="course-degree-ladder"><div class="course-degree-node positive"><b>POSITIVE</b><span>as bright as</span></div><span>→</span><div class="course-degree-node comparative"><b>COMPARATIVE</b><span>brighter than</span></div><span>→</span><div class="course-degree-node superlative"><b>SUPERLATIVE</b><span>the brightest</span></div></div></div>';
      if(slide.type==='compare'||v==='compare')return '<div class="course-visual-v3"><div class="course-degree-dual"><div><b>EQUALITY</b><span>as + adjective + as</span></div><i>⇄</i><div><b>RANKING</b><span>-er / more · -est / most</span></div></div></div>';
      if(slide.type==='examples'||v==='examples')return '<div class="course-visual-v3"><div class="course-degree-flow"><div><b>CLUE</b><span>signal word</span></div><i>→</i><div><b>FORM</b><span>degree choice</span></div><i>→</i><div><b>MEANING</b><span>sentence check</span></div></div></div>';
      if(slide.type==='table'||v==='table')return '<div class="course-visual-v3"><div class="course-degree-matrix"><div><b>1</b><span>Degree</span></div><div><b>2</b><span>Clue</span></div><div><b>3</b><span>Noun</span></div></div></div>';
      return '<div class="course-visual-v3"><div class="course-degree-flow"><div><b>FORM</b><span>base adjective</span></div><i>→</i><div><b>CHANGE</b><span>more / -er</span></div><i>→</i><div><b>GROUP</b><span>most / -est</span></div></div></div>';
    }
    if(v==='focus')return '<div class="course-visual-v3"><div class="course-3d-stage"><div class="course-3d-node">Subject<small>doer / কাজ করে</small></div><span class="course-3d-arrow">→</span><div class="course-3d-node">Verb<small>action / কাজ</small></div><span class="course-3d-arrow">→</span><div class="course-3d-node">Object<small>receiver / প্রভাব নেয়</small></div></div></div>';
    if(v==='compare')return '<div class="course-visual-v3"><div class="course-split-visual"><div class="course-split-side active"><b>ACTIVE</b><span>Doer focus</span><strong>Subject → Verb → Object</strong></div><div class="course-split-arrow">⇄</div><div class="course-split-side passive"><b>PASSIVE</b><span>Receiver focus</span><strong>Object → be + V3</strong></div></div></div>';
    if(v==='examples')return '<div class="course-visual-v3"><div class="course-timeline-visual"><span>TIME</span><i></i><b>PRESENT</b><i></i><b>PAST</b><i></i><b>FUTURE</b></div></div>';
    if(v==='table')return '<div class="course-visual-v3"><div class="course-matrix-visual"><div><b>1</b><span>Tense</span></div><div><b>2</b><span>Helper</span></div><div><b>3</b><span>V3</span></div></div></div>';
    if(v==='filter')return '<div class="course-visual-v3"><div class="course-filter-v3"><div class="course-3d-node">Sentence<small>object আছে?</small></div><span class="course-filter-funnel">⬇</span><div class="course-3d-node">Passive test<small>be + V3</small></div></div></div>';
    if(v==='exam')return '<div class="course-visual-v3"><div class="course-orbit"><div class="course-orbit-core">🎯</div></div></div>';
    return '<div class="course-visual-v3"><div class="course-3d-stage"><div class="course-3d-node">Tense<small>সময় ধরো</small></div><span class="course-3d-arrow">+</span><div class="course-3d-node">be / being / been<small>helper</small></div><span class="course-3d-arrow">+</span><div class="course-3d-node">V3<small>past participle</small></div></div></div>';
  }
  function slideMarkup(slide,course){
    const anchor=slide.visual?visual(slide,course):visual({visual:slide.type==='compare'?'compare':slide.type==='examples'?'examples':slide.type==='table'?'table':'formula'},course);
    let body='';
    if(slide.type==='compare')body=`${anchor}<div class="course-compare-grid">${(slide.columns||[]).map(c=>`<div class="course-compare ${esc(c.tone||'green')}"><div class="course-compare-label">${esc(c.label)}</div><div class="course-compare-title">${esc(c.title)}</div><div class="course-compare-body">${esc(c.body)}</div></div>`).join('')}</div>`;
    else if(slide.type==='table')body=`${anchor}<div class="course-table-scroll"><table class="course-table"><tbody>${(slide.rows||[]).map(r=>`<tr>${r.map((cell,i)=>`<td class="course-table-cell-${i}">${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
    else if(slide.type==='examples')body=`${anchor}<div class="course-example-list">${(slide.items||[]).map(x=>`<div class="course-example-row"><b>${esc(x[0])}</b><span>${esc(x[1])}</span><span>→ ${esc(x[2])}</span></div>`).join('')}</div>`;
    else body=`${anchor}<div class="course-rule-box">${esc(slide.rule||slide.formula||'')}</div>${slide.steps?`<div class="course-steps">${slide.steps.map((s,i)=>`<div class="course-step"><em>${i+1}</em><span>${esc(s)}</span></div>`).join('')}</div>`:''}<div class="course-example">${esc(slide.example||'')}</div>`;
    return `${body}${slide.note?`<div class="course-note-box"><strong>মনে রাখবে</strong>${esc(slide.note)}</div>`:''}`;
  }
  function renderLibrary(){inject();const list=courses();return shell(`<div class="course-page"><section class="course-hero"><div class="course-kicker">ADMISSION HUB · COURSE LIBRARY</div><h1 class="course-title">Visual Courses</h1><p class="course-subtitle">PDF থেকে visual lessons ও practice</p><div class="course-meta"><span class="course-pill">${list.length} Courses</span><span class="course-pill">Manual course library</span></div></section><div class="course-bank-tools"><button class="course-btn secondary" type="button" onclick="navigate('courses/manage')">Manage Courses</button></div><h2 class="course-section-title">চলমান Courses</h2><div class="course-list">${list.map((c,i)=>{const p=coursePct(c);return `<article class="course-lesson-card"><span class="course-lesson-icon">${c.icon||'📘'}</span><span class="course-lesson-info"><b>${esc(c.title)}</b><small>${esc(c.subtitle||'Visual learning course')} · ${esc(c.subject||'General')}</small><div class="course-progress"><i style="--course-pct:${p}%"></i></div><small>${p}% completed · ${(c.lessons||[]).length} lessons · ${courseQuestions(c).length} MCQs</small></span><button class="course-btn secondary" type="button" onclick="navigate('courses/${esc(c.id)}')">Open</button></article>`}).join('')}</div><div class="course-note-box"><strong>Manual launch</strong>প্রতিটি নতুন Course আলাদা PDF ও topic বুঝে manually তৈরি করা হবে। একই pattern সব Course-এ ব্যবহার করা হবে না।</div></div>`,'Courses')}
  function renderManage(){inject();const builtIns=[BASE,...EXTRA],custom=customCourses(),all=courses(),drafts=custom.filter(c=>(c.status||'draft')==='draft').length,reviews=custom.filter(c=>c.status==='review').length,published=custom.filter(c=>c.status==='published').length;return shell(`<div class="course-page"><button class="course-back" type="button" onclick="navigate('courses')">← Course Library</button><section class="course-hero"><div class="course-kicker">COURSE MANAGEMENT</div><h1 class="course-title">Manage Courses</h1><p class="course-subtitle">ম্যানুয়ালি যোগ করা Course-এর status ও content count এক জায়গা থেকে দেখো। Built-in course locked থাকবে।</p><div class="course-meta"><span class="course-pill">${all.length} total</span><span class="course-pill">${drafts} draft</span><span class="course-pill">${reviews} review</span><span class="course-pill">${published+builtIns.length} published</span></div></section><div class="course-manage-actions"><button class="course-btn secondary" type="button" onclick="navigate('courses')">Open Library</button></div><div class="course-manage-toolbar"><input aria-label="Search courses" placeholder="Search courses..." oninput="window.courseManageSearch(this.value)"><select aria-label="Filter course status" onchange="window.courseManageStatus(this.value)"><option value="all">All statuses</option><option value="draft">Draft</option><option value="review">Review</option><option value="published">Published</option></select></div><div class="course-manage-grid" id="courseManageGrid"><div class="course-manage-card course-manage-item" data-course-title="${esc(BASE.title).toLowerCase()}" data-course-status="published"><div class="course-manage-card-head"><span class="course-status published">PUBLISHED · BUILT-IN</span><span class="course-lock">LOCKED</span></div><h3>${esc(BASE.title)}</h3><p class="course-muted">PDF source course · ${(BASE.lessons||[]).length} lessons · ${courseQuestions(BASE).length} MCQs</p><div class="course-manage-card-footer"><small>Source-safe · delete disabled</small><button class="course-link-btn" type="button" onclick="navigate('courses/${esc(BASE.id)}')">Open →</button></div></div>${EXTRA.map(c=>`<div class="course-manage-card course-manage-item" data-course-title="${esc(c.title).toLowerCase()}" data-course-status="published"><div class="course-manage-card-head"><span class="course-status published">PUBLISHED · BUILT-IN</span><span class="course-lock">LOCKED</span></div><h3>${esc(c.title)}</h3><p class="course-muted">Source PDF · ${(c.lessons||[]).length} lessons · ${courseQuestions(c).length} MCQs</p><div class="course-manage-card-footer"><small>Source-safe · delete disabled</small><button class="course-link-btn" type="button" onclick="navigate('courses/${esc(c.id)}')">Open →</button></div></div>`).join('')}${custom.length?custom.map(c=>{const status=c.status||'draft';return `<div class="course-manage-card course-manage-item" data-course-title="${esc(c.title).toLowerCase()}" data-course-status="${esc(status)}"><div class="course-manage-card-head"><span class="course-status ${esc(status)}">${esc(status).toUpperCase()}</span><span class="course-manage-count">${(c.lessons||[]).length}L · ${courseQuestions(c).length}Q</span></div><h3>${esc(c.title)}</h3><p class="course-muted">${esc(c.subtitle||'Local course draft')}</p><div class="course-manage-card-footer"><small>Local draft · editable</small><div class="course-manage-inline"><button class="course-link-btn" type="button" onclick="navigate('courses/${esc(c.id)}')">Open →</button>${status==='draft'?`<button class="course-link-btn" type="button" onclick="window.courseSetStatus('${esc(c.id)}','review')">Review</button>`:status==='review'?`<button class="course-link-btn" type="button" onclick="window.courseSetStatus('${esc(c.id)}','published')">Publish</button>`:''}<button class="course-link-btn danger" type="button" onclick="window.courseDelete('${esc(c.id)}')">Delete</button></div></div></div>`}).join(''):'<div class="course-manage-card course-manage-empty"><h3>কোনো custom course নেই</h3><p class="course-muted">নতুন Course তুমি বললে Juju আলাদা content structure-এ manually যোগ করবে।</p></div>'}</div></div>`,'Manage Courses')}
  function renderNew(){inject();return shell(`<div class="course-page"><button class="course-back" type="button" onclick="navigate('courses')">← Course Library</button><section class="course-hero"><div class="course-kicker">NEW COURSE · DRAFT</div><h1 class="course-title">PDF Course Draft</h1><p class="course-subtitle">Source, lesson structure ও MCQ আগে review করো; তারপর local Draft save করো। Auto-publish হবে না।</p></section><form class="course-form" onsubmit="window.courseCreateFromForm(event)"><label>Course title<input id="courseNewTitle" required oninput="window.courseDraftValidate()" placeholder="যেমন: Narration Mastery"></label><label>Subject<input id="courseNewSubject" placeholder="English Grammar"></label><label>Subtitle<input id="courseNewSubtitle" placeholder="Direct & Indirect Speech"></label><label>Source PDF (optional)<input id="courseNewPdf" type="file" accept="application/pdf" onchange="window.courseReadPdf(this);window.courseDraftValidate()"><small id="coursePdfStatus" class="course-form-help">PDF select করলে শুধু source name draft-এ থাকবে; parser replacement এখনও manual review-based।</small></label><label>Lesson content<textarea id="courseNewLessons" required oninput="window.courseDraftValidate()" placeholder="# Lesson 1: Core Rule\nObject + rule + example\n\n# Lesson 2: Practice\nMore examples and rules"></textarea></label><label>Optional MCQ JSON<textarea id="courseNewMcqs" oninput="window.courseDraftValidate()" placeholder='[{"q":"Question?","o":["A","B","C","D"],"a":0,"e":"Explanation"}]'></textarea></label><section class="course-draft-checklist" aria-live="polite"><div class="course-draft-check-head"><b>Draft QA checklist</b><span id="courseDraftScore">0/4 ready</span></div><div class="course-draft-checks"><span id="courseCheckTitle">○ Title</span><span id="courseCheckSource">○ Source note</span><span id="courseCheckLessons">○ Lesson structure</span><span id="courseCheckMcq">○ MCQ format</span></div></section><p class="course-form-help">প্রতি blank line একটি slide block হবে। MCQ JSON দিলে প্রতিটি প্রশ্নে unique A-D option এবং 0–3 correct index বাধ্যতামূলক। কোনো existing Question Bank data বদলাবে না।</p><button class="course-btn" type="submit">Save as Draft</button></form></div>`,'New Course')}
  function renderCourseCockpit(c,p,pctDone,qs){const lessons=c.lessons||[],totalSlides=lessons.reduce((n,l)=>n+(l.slides||[]).length,0),validIds=new Set(qs.map(q=>q.id)),answered=Object.keys(p.stats||{}).filter(id=>validIds.has(id)).length,attempts=qs.reduce((n,q)=>n+Number(qStats(c,q.id).attempts||0),0),correct=qs.reduce((n,q)=>n+Number(qStats(c,q.id).correct||0),0),mistakes=qs.filter(q=>Number(qStats(c,q.id).wrong||0)>0).length,bookmarks=Object.keys(p.bookmarks||{}).filter(id=>validIds.has(id)&&p.bookmarks[id]).length,accuracy=pct(correct,attempts),last=lessons.find(l=>l.id===p.lastLesson)||lessons[0],lastSlide=Math.min(Number(p.lastSlide)||0,Math.max(0,(last?.slides||[]).length-1)),record=resultAll()[c.id]||{},history=record.history?.length?record.history:(record.answers?[record]:[]),families={};qs.forEach(q=>{const st=qStats(c,q.id);if(Number(st.attempts||0)){const f=q.family||'Core rules';families[f]??={attempts:0,correct:0};families[f].attempts+=Number(st.attempts||0);families[f].correct+=Number(st.correct||0)}});const familyRows=Object.entries(families).sort((a,b)=>pct(a[1].correct,a[1].attempts)-pct(b[1].correct,b[1].attempts)).slice(0,3).map(([name,x])=>`<div class="course-cockpit-topic"><span>${esc(name)}</span><b>${pct(x.correct,x.attempts)}%</b><i><em style="width:${pct(x.correct,x.attempts)}%"></em></i></div>`).join('');const scoreOf=h=>{const a=Object.values(h.answers||{});return pct(a.filter(x=>x.correct).length,a.length)};const trend=history.slice(0,5).reverse(),trendBars=trend.map((h,i)=>`<span style="height:${Math.max(8,scoreOf(h))}%" title="Attempt ${i+1}: ${scoreOf(h)}%">${scoreOf(h)}%</span>`).join('');return `<section class="course-cockpit"><header class="course-cockpit-head"><div><div class="course-kicker">STUDY COCKPIT</div><h2>তোমার পরের সেরা পদক্ষেপ</h2><p>${last?`শেষ পড়া: ${esc(last.title)}`:'একটি lesson দিয়ে শুরু করো'} · ${lessons.length} lessons · ${totalSlides} slides</p></div><div class="course-cockpit-ring" style="--score:${pctDone}"><span>${pctDone}%<small>complete</small></span></div></header><div class="course-cockpit-stats"><div><b>${completedCount(c)}/${lessons.length}</b><small>Lessons done</small></div><div><b>${answered}</b><small>Questions tried</small></div><div><b>${accuracy}%</b><small>Practice accuracy</small></div><div><b>${mistakes}</b><small>Needs revision</small></div><div><b>${bookmarks}</b><small>Bookmarks</small></div><div><b>${history.length}</b><small>Saved results</small></div></div><div class="course-cockpit-actions"><button class="course-btn" type="button" onclick="window.courseResume('${esc(c.id)}')">▶ ${p.lastLesson?'Resume lesson':'Start lesson'}</button><button class="course-btn secondary" type="button" onclick="window.courseQuickReview('${esc(c.id)}','mistakes')">Review mistakes</button><button class="course-btn secondary" type="button" onclick="window.courseQuickReview('${esc(c.id)}','bookmarked')">Bookmarks</button><button class="course-btn secondary" type="button" onclick="window.courseQuickReview('${esc(c.id)}','unattempted')">Unattempted</button><button class="course-btn secondary" type="button" onclick="navigate('courses/${esc(c.id)}/result')">Result Sheet</button></div><div class="course-cockpit-grid"><article class="course-cockpit-card course-cockpit-resume"><span class="course-cockpit-label">RESUME POINT</span><strong>${last?esc(last.title):'প্রথম lesson'}</strong><small>${last?`Slide ${lastSlide+1}/${(last.slides||[]).length} · ${p.lessons?.[last.id]?'Completed':'In progress'}`:'Ready to begin'}</small><button class="course-link-btn" type="button" onclick="window.courseResume('${esc(c.id)}')">Open point →</button></article><article class="course-cockpit-card"><span class="course-cockpit-label">WEAK TOPICS</span>${familyRows||'<p class="course-cockpit-empty">কিছু practice করলে topic insight দেখা যাবে।</p>'}</article><article class="course-cockpit-card course-cockpit-trend"><div class="course-cockpit-trend-head"><span class="course-cockpit-label">RESULT TREND</span><small>${trend.length?`Latest ${scoreOf(trend[trend.length-1])}% · Best ${Math.max(...trend.map(scoreOf))}%`:'প্রথম attempt-এর পর দেখা যাবে'}</small></div><div class="course-trend-bars">${trendBars||'<span class="course-trend-empty">Saved Result Sheet করলে score trend তৈরি হবে।</span>'}</div></article></div><div class="course-cockpit-roadmap"><div class="course-cockpit-roadmap-head"><span class="course-cockpit-label">LEARNING ROADMAP</span><small>${pctDone}% complete</small></div>${lessons.map((l,i)=>`<button class="course-roadmap-row" type="button" onclick="navigate('courses/${esc(c.id)}/lesson/${esc(l.id)}/slide/0')"><span class="course-roadmap-dot ${p.lessons?.[l.id]?'done':''}">${p.lessons?.[l.id]?'✓':i+1}</span><span><b>${esc(l.title)}</b><small>${(l.slides||[]).length} slides · ${p.lessons?.[l.id]?'Completed':'Open lesson'}</small></span><i>${p.lessons?.[l.id]?'Done':'›'}</i></button>`).join('')}</div><div class="course-cockpit-footer"><span>Source-safe course data · built-in questions remain separate</span><span>${qs.length} MCQs · ${totalSlides} visual slides</span></div></section>`}
  function renderOverview(c){inject();const p=courseProgress(c.id),pctDone=coursePct(c),qs=courseQuestions(c);return shell(`<div class="course-page"><button class="course-back" type="button" onclick="navigate('courses')">← সব Courses</button><section class="course-hero"><div class="course-kicker">${esc(c.level||'COURSE')}</div><h1 class="course-title">${esc(c.title)}</h1><p class="course-subtitle">${esc(c.subtitle||'Visual learning course')}</p><div class="course-meta"><span class="course-pill">📚 ${esc(c.subject||'General')}</span><span class="course-pill">⏱ ${esc(c.time||'Self paced')}</span><span class="course-pill">🎯 ${qs.length} MCQs</span></div><div class="course-progress"><i style="--course-pct:${pctDone}%"></i></div><span class="course-progress-label">${pctDone}% course completed</span></section>${c.sourceNote?`<div class="course-note-box course-source-note"><strong>Source & practice scope</strong>${esc(c.sourceNote)}</div>`:''}${renderCourseCockpit(c,p,pctDone,qs)}<div class="course-overview-grid"><div class="course-stat"><b>${(c.lessons||[]).length}</b><small>Lessons</small></div><div class="course-stat"><b>${qs.length}</b><small>Practice MCQ</small></div><div class="course-stat"><b>${Object.keys(p.stats||{}).length}</b><small>Answered</small></div></div><h2 class="course-section-title">Lesson sequence</h2><div class="course-list">${(c.lessons||[]).map((l,i)=>`<button class="course-lesson-card" type="button" onclick="navigate('courses/${esc(c.id)}/lesson/${esc(l.id)}/slide/0')"><span class="course-lesson-icon">${l.icon||'📖'}</span><span class="course-lesson-info"><b>${esc(lessonLabel(l,i))}</b><small>${(l.slides||[]).length} visual slides · ${p.lessons?.[l.id]?'Completed':'Not started'}</small></span><span class="course-check ${p.lessons?.[l.id]?'done':''}">${p.lessons?.[l.id]?'✓':'›'}</span></button>`).join('')}<button class="course-lesson-card" type="button" onclick="navigate('courses/${esc(c.id)}/exam')"><span class="course-lesson-icon">🎯</span><span class="course-lesson-info"><b>Exam Zone: Question Bank cards</b><small>${qs.length} questions · bookmark, answer, notes, edit, duplicate, delete</small></span><span class="course-check">›</span></button></div></div>`,c.title)}
  function renderLessonRail(c,l,i){const slides=l.slides||[],lessonIndex=(c.lessons||[]).findIndex(x=>x.id===l.id),courseDone=coursePct(c);return `<div class="course-lesson-rail"><div class="course-lesson-rail-top"><span class="course-lesson-breadcrumb">${esc(c.title)} · Lesson ${lessonIndex+1}/${(c.lessons||[]).length}</span><span class="course-lesson-status">${courseDone}% course progress</span></div><div class="course-lesson-progress"><i style="width:${Math.round((i+1)/Math.max(1,slides.length)*100)}%"></i></div><nav class="course-slide-map" aria-label="Slide map">${slides.map((x,n)=>`<button class="course-slide-dot ${n===i?'active':''} ${n<i?'visited':''}" type="button" aria-label="Slide ${n+1}" onclick="navigate('courses/${esc(c.id)}/lesson/${esc(l.id)}/slide/${n}')"><span>${n<i?'✓':n+1}</span><small>${n===i?'Current':n<i?'Seen':'Next'}</small></button>`).join('')}</nav></div>`}
  const slideInsight=(s,c)=>c?.id==='parts-of-speech-mastery'?(s.note||s.rule||s.formula||(s.type==='compare'?'দুই পাশের POS function, form ও signal একসাথে মিলিয়ে দেখো।':s.type==='table'?'Right-side, modify ও object test চালিয়ে answer ধরো।':'এই slide-এর word-এর sentence job আগে নির্ণয় করো.')):c?.id==='phrase-clause-mastery'?(s.note||s.rule||s.formula||(s.type==='compare'?'দুই পাশের group-এর finite verb ও sentence function মিলিয়ে দেখো।':s.type==='table'?'Subject + finite verb detector দিয়ে phrase/clause boundary ঠিক করো।':'এই slide-এর group, connector ও function একসাথে মিলিয়ে দেখো।')):(s.note||s.rule||s.formula||(s.type==='examples'?'উদাহরণগুলো মিলিয়ে tense অনুযায়ী be / being / been এবং V3 ধরো।':s.type==='compare'?'দুই পাশের pattern দেখে কোন অংশ বদলেছে আর কোন অংশ একই আছে আলাদা করো.':s.type==='table'?'টেবিল থেকে auxiliary, V3 ও object position একসাথে মিলিয়ে নাও.':'এই slide-এর মূল pattern ধরো।'));
  function renderLesson(c,l,idx){inject();const slides=l.slides||[],i=Math.max(0,Math.min(Number(idx)||0,Math.max(0,slides.length-1))),s=slides[i]||{title:'Empty slide',type:'rule'},p=courseProgress(c.id);saveCourseProgress(c.id,{lastLesson:l.id,lastSlide:i});return shell(`<div class="course-slide-wrap"><button class="course-back" type="button" onclick="navigate('courses/${esc(c.id)}')">← Lesson list</button>${renderLessonRail(c,l,i)}<div class="course-slide-head"><span>${esc(l.title)}</span><span class="course-slide-count">${esc((s.type||'lesson').toUpperCase())} · Slide ${i+1}/${slides.length}</span></div><article class="course-slide-card"><div class="course-eyebrow">${esc(s.eyebrow||'VISUAL LESSON')}</div><h1 class="course-slide-title">${esc(s.title||'Lesson')}</h1>${s.lead?`<p class="course-lead">${esc(s.lead)}</p>`:''}${slideMarkup(s,c)}</article><aside class="course-slide-insight"><span>KEY INSIGHT</span><strong>${esc(slideInsight(s,c))}</strong></aside><div class="course-slide-actions"><button class="course-btn secondary" type="button" ${i===0?'disabled':''} onclick="navigate('courses/${esc(c.id)}/lesson/${esc(l.id)}/slide/${i-1}')">← Back</button>${i<slides.length-1?`<button class="course-btn" type="button" onclick="navigate('courses/${esc(c.id)}/lesson/${esc(l.id)}/slide/${i+1}')">Next slide →</button>`:`<button class="course-btn" type="button" onclick="window.courseComplete('${esc(c.id)}','${esc(l.id)}')">${p.lessons?.[l.id]?'Completed ✓':'Complete lesson ✓'}</button>`}</div></div>`,c.title)}
  let examSession=null;
  const exam=()=>examSession||(examSession={courseId:'',page:0,query:'',filter:'all',answers:{},show:{},editId:null,startedAt:Date.now()});
  const qStats=(c,id)=>courseProgress(c.id).stats?.[id]||{attempts:0,correct:0,wrong:0};
  function renderEdit(c,q){const e=exam();if(e.editId!==q.id)return '';return `<div class="course-edit-box"><b>Edit question</b><label>Question<input id="courseEditQ" value="${esc(q.q)}"></label>${q.o.map((x,i)=>`<label>Option ${String.fromCharCode(65+i)}<input id="courseEditO${i}" value="${esc(x)}"></label>`).join('')}<label>Explanation<textarea id="courseEditE">${esc(q.e||'')}</textarea></label><label>Correct option (A-D)<input id="courseEditA" value="${String.fromCharCode(65+Number(q.a||0))}" maxlength="1"></label><div class="course-slide-actions"><button class="course-btn secondary" type="button" onclick="window.courseCancelEdit()">Cancel</button><button class="course-btn" type="button" onclick="window.courseSaveEdit('${esc(c.id)}','${esc(q.id)}')">Save edit</button></div></div>`}
  function renderExamUtility(c,qs,filtered,e,page,maxPage,filter){const p=courseProgress(c.id),pageSize=10,totalPages=Math.max(1,Math.ceil(filtered.length/pageSize)),answered=Object.keys(e.answers||{}).length,bookmarks=Object.keys(p.bookmarks||{}).filter(id=>p.bookmarks[id]).length,elapsed=Math.max(0,Date.now()-(e.startedAt||Date.now())),mins=Math.floor(elapsed/60000),secs=String(Math.floor(elapsed/1000)%60).padStart(2,'0');return `<div class="course-exam-utility"><div class="course-exam-utility-top"><span><b>${filtered.length}</b> matching · <b>${answered}</b> answered</span><span class="course-exam-timer">Session ${mins}:${secs}</span></div><div class="course-exam-quick"><button class="course-bank-chip" type="button" onclick="window.courseJumpTarget('${esc(c.id)}','unattempted')">Review unattempted</button><button class="course-bank-chip" type="button" onclick="window.courseJumpTarget('${esc(c.id)}','mistakes')">Review mistakes</button><button class="course-bank-chip" type="button" onclick="window.courseJumpTarget('${esc(c.id)}','bookmarked')">Review bookmarks</button><span class="course-exam-bookmark-count">★ ${bookmarks}</span></div><div class="course-exam-pagebar"><span>Page ${page+1}/${totalPages}</span><label>Jump<select aria-label="Jump to question page" onchange="window.courseJumpPage('${esc(c.id)}',this.value)">${Array.from({length:totalPages},(_,i)=>`<option value="${i}" ${i===page?'selected':''}>${i+1}</option>`).join('')}</select></label><label>Order<select aria-label="Order questions" onchange="window.courseSortV3('${esc(c.id)}',this.value)"><option value="default" ${e.order!=='weak'&&e.order!=='mistakes'?'selected':''}>Original order</option><option value="mistakes" ${e.order==='mistakes'?'selected':''}>Mistakes first</option><option value="weak" ${e.order==='weak'?'selected':''}>Weak topics first</option></select></label><span class="course-exam-keyhint">Keys 1–4 answer</span></div></div>`}
